const input=$json.body??$json;
const outcome=String(input.outcome??input.negotiation_outcome??input.status??'').toLowerCase();
const mao=Number(input.dynamic_mao??input.adjusted_mao??input.mao??0);
const amount=Number(input.counteroffer_amount??input.contract_price??input.offer_price??0);
const dnc=input.dnc===true||outcome==='blocked_dnc';
const within=mao>0&&amount>0&&amount<=mao;
let route='needs_review',next='WF-126',reason='negotiation outcome requires review';
if(dnc){route='blocked_dnc';next='WF-126';reason='DNC/contact restriction';}
else if(outcome==='contract_decision_ready'||outcome==='accept_counteroffer'||outcome==='accept_offer'){
  if(mao>0&&amount>mao){route='blocked_above_mao';next='WF-126';reason='contract price exceeds protected dynamic MAO';}
  else {route='contract_trigger';next='WF-321';reason='seller agreement is contract-ready within protected MAO';}
}
else if(outcome==='revised_offer'){route='revised_offer_followup';next='WF-315';reason='controlled revised offer required';}
else if(outcome==='walk_away_or_reengage'||outcome==='reengage'||outcome==='rejected'||outcome==='timeout_followup'){route='rejection_reengagement';next='WF-321';reason='seller is not currently contract-ready';}
else if(outcome==='clarification_response'){route='clarification_followup';next='WF-315';reason='seller clarification required before final decision';}
return [{json:{...input,workflow_id:'WF-320',workflow_name:'Negotiation Outcome → Contract Trigger / Rejection / Re-engagement Controller',route,reason,dynamic_mao:mao,proposed_contract_price:amount||null,mao_protected:mao>0,within_mao:within,next_workflow:next,human_review_required:['contract_trigger','blocked_above_mao','rejection_reengagement'].includes(route),crm_activity:{activity_type:'negotiation_route',deal_id:input.deal_id,lead_id:input.lead_id,property_id:input.property_id,status:route,contract_price:amount||null,reason}}}];
